<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {useI18n} from 'vue-i18n'
import {api,write,errorMessage} from '../lib/api'
import {pushPayload} from '../lib/requests'
import {state,saveSettings,time,formatValue,unit} from '../lib/state'
import {clone} from '../lib/geometry'
import {mergeDiscovery,failedPreview,restoreDiscovery,sensorCatalogue,macKey,type CatalogueSensor} from '../lib/discovery'
import {installApp,installPrompt} from '../lib/pwa'
import type {Settings,Sensor,Discovered,SensorPreview,SystemSettings} from '../lib/types'
import Notice from '../components/Notice.vue'
import Icon from '../components/Icon.vue'
const {t}=useI18n()
const form=reactive<Settings>(clone(state.settings)),system=reactive<SystemSettings>({sample_interval_seconds:900,stale_after_seconds:1800}),sensors=ref<Sensor[]>([]),status=ref<{mode:string;collector:string;storage:string;last_error:string|null;push_available:boolean}|null>(null),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),scanning=ref(false),devices=ref<Discovered[]>([]),scanned=ref(false),readingAddresses=ref<Set<string>>(new Set())
const sensorOpen=ref(false),editing=ref(''),sensorError=ref(''),sensor=reactive({name:'',address:'',enabled:true,sample_interval_seconds:900}),inheritInterval=ref(true),pushAvailable=ref(false),pushKey=ref<string|null>(null),pushSubscription=ref<PushSubscription|null>(null),pushBusy=ref(false)
const sensorRows=computed(()=>sensorCatalogue(devices.value,sensors.value))
const pushSupported=computed(()=>isSecureContext&&'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window)
async function load(){loading.value=true;error.value='';try{const [settings,ss,sen,st,key]=await Promise.all([api<Settings>('/settings'),api<SystemSettings>('/system/settings'),api<Sensor[]>('/sensors'),api<NonNullable<typeof status.value>>('/system/status'),api<{available:boolean;public_key:string|null}>('/push/key')]);state.settings=settings;Object.assign(form,clone(settings));Object.assign(system,ss);sensors.value=sen;status.value=st;pushAvailable.value=key.available;pushKey.value=key.public_key;if(pushSupported.value){const reg=await navigator.serviceWorker.getRegistration('/');pushSubscription.value=await reg?.pushManager.getSubscription()??null}}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function saveDisplay(){busy.value=true;error.value='';message.value='';try{await saveSettings(clone(form));Object.assign(form,clone(state.settings));message.value=t('saved')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function saveSystem(){busy.value=true;error.value='';message.value='';try{Object.assign(system,await write<SystemSettings>('/system/settings',system,'PATCH'));message.value=t('saved')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function discover(){scanning.value=true;error.value='';try{const result=await write<{devices:Discovered[]}>('/sensors/discover',{});devices.value=mergeDiscovery(devices.value,result.devices);scanned.value=true;await Promise.all(devices.value.filter(device=>device.seen_in_scan&&device.protocol==='lt_thermometer').map(readPreview))}catch(e){error.value=errorMessage(e)}finally{scanning.value=false}}
async function readPreview(device:Discovered){const key=macKey(device.address);if(readingAddresses.value.has(key))return;readingAddresses.value.add(key);device.measurement_error=false;try{const sample=await write<SensorPreview>('/sensors/preview',{address:device.address});Object.assign(device,sample,{available:true,seen_in_scan:true});const saved=registeredDevice(device);if(saved)Object.assign(saved,{temperature:sample.temperature,humidity:sample.humidity,last_seen:sample.timestamp,available:true,read_state:'ready'});await refreshSensorValues()}catch{failedPreview(device);await refreshSensorValues()}finally{readingAddresses.value.delete(key)}}
function registeredDevice(device:Discovered){return sensors.value.find(value=>value.address&&macKey(value.address)===macKey(device.address))}
function readRow(row:CatalogueSensor){if(!row.address)return;const device=row.device??{name:row.name,address:row.address,rssi:row.rssi??0,protocol:row.protocol,service_uuids:[],manufacturer_data:{},service_data:{}};return readPreview(device)}
function rowStatus(row:CatalogueSensor){if(readingAddresses.value.has(row.key))return 'readingSensor';if(row.available)return 'online';if(row.read_state==='retrying')return 'retryingSensor';if(row.read_state==='reading')return 'readingSensor';if(row.read_state==='waiting'||row.available==null)return 'measurementPending';return 'unavailable'}
const discoveryCacheKey='sensogrid.discovery.v1.'+(state.auth?.user?.username??'local')
watch(devices,()=>{try{localStorage.setItem(discoveryCacheKey,JSON.stringify(devices.value))}catch{/* Discovery remains usable when browser storage is unavailable. */}},{deep:true})
function showSensor(value?:Sensor|Discovered){inheritInterval.value=!(value&&'id' in value&&value.interval_override_seconds!=null);sensorError.value='';editing.value=value&&'id' in value?value.id:'';Object.assign(sensor,{name:value?.name??'',address:value?.address??'',enabled:value&&'enabled' in value?value.enabled:true,sample_interval_seconds:value&&'sample_interval_seconds' in value?value.sample_interval_seconds:system.sample_interval_seconds});sensorOpen.value=true}
async function saveSensor(){busy.value=true;sensorError.value='';try{if(editing.value)await write('/sensors/'+encodeURIComponent(editing.value),{name:sensor.name,enabled:sensor.enabled,sample_interval_seconds:inheritInterval.value?null:sensor.sample_interval_seconds},'PATCH');else{const created=await write<Sensor>('/sensors',{name:sensor.name,address:sensor.address,room_id:null,protocol:'lt_thermometer'});editing.value=created.id;if(!inheritInterval.value||!sensor.enabled)await write('/sensors/'+encodeURIComponent(created.id),{enabled:sensor.enabled,sample_interval_seconds:inheritInterval.value?null:sensor.sample_interval_seconds},'PATCH')}sensors.value=await api<Sensor[]>('/sensors');sensorOpen.value=false;message.value=t('saved')}catch(e){sensorError.value=errorMessage(e)}finally{busy.value=false}}
async function removeSensor(value:Sensor){if(!confirm(t('confirmDelete')+' '+value.name+' '+t('deleteSensorHint')))return;error.value='';try{await api('/sensors/'+encodeURIComponent(value.id),{method:'DELETE'});sensors.value=sensors.value.filter(s=>s.id!==value.id)}catch(e){error.value=errorMessage(e)}}
function keyBytes(key:string){const raw=atob(key.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(key.length/4)*4,'='));const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes}
async function enablePush(){if(!pushKey.value||!pushSupported.value)return;pushBusy.value=true;error.value='';message.value='';try{const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error(t('pushDenied'));const registration=await navigator.serviceWorker.getRegistration('/')??await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;const subscription=await registration.pushManager.getSubscription()??await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(pushKey.value)});await write('/push/subscriptions',pushPayload(subscription,navigator.userAgent));pushSubscription.value=subscription;await saveSettings({push_enabled:true});form.push_enabled=true;message.value=t('pushSubscribed')}catch(e){error.value=errorMessage(e)}finally{pushBusy.value=false}}
async function disablePush(){if(!pushSubscription.value)return;pushBusy.value=true;error.value='';try{await write('/push/subscriptions',{endpoint:pushSubscription.value.endpoint},'DELETE');await pushSubscription.value.unsubscribe();pushSubscription.value=null;message.value=t('pushUnsubscribed')}catch(e){error.value=errorMessage(e)}finally{pushBusy.value=false}}
async function testPush(){pushBusy.value=true;error.value='';message.value='';try{const result=await write<{sent:number;failed:number}>('/push/test',{});if(result.sent>0)message.value=t('pushSentCount',{sent:result.sent});if(result.failed>0)error.value=t('pushFailedCount',{failed:result.failed});else if(!result.sent)error.value=t('pushNoRecipients')}catch(e){error.value=errorMessage(e)}finally{pushBusy.value=false}}
let sensorRefresh:ReturnType<typeof setInterval>|undefined
let refreshingSensors=false
async function refreshSensorValues(){if(refreshingSensors)return;refreshingSensors=true;try{sensors.value=await api<Sensor[]>('/sensors')}catch{/* Last measurement timestamp remains visible when disconnected. */}finally{refreshingSensors=false}}
onMounted(()=>{try{devices.value=restoreDiscovery(localStorage.getItem(discoveryCacheKey));scanned.value=devices.value.length>0}catch{/* Browser storage unavailable. */}void load();sensorRefresh=setInterval(()=>void refreshSensorValues(),5000)})
onUnmounted(()=>clearInterval(sensorRefresh))
</script>
<template>
<main class="page settings-page">
<header class="page-header"><div><div class="eyebrow">SENSOGRID / {{ t('settings') }}</div><h1>{{ t('settings') }}</h1><p>{{ t('local') }}</p></div><span v-if="status?.mode==='demo'" class="tag warn">{{ t('demo') }}</span></header><Notice v-if="error" kind="error">{{ t('requestFailed') }}<details open><summary>{{ t('details') }}</summary>{{ error }}</details></Notice><Notice v-if="message" kind="success">{{ message }}</Notice><div v-if="loading" class="skeleton plan" :aria-label="t('loading')"></div><template v-else>
<form @submit.prevent="saveDisplay"><section class="settings-section"><div><h2>{{ t('general') }}</h2><p>SensoGrid / {{ state.auth?.user?.username }}</p></div><div class="form-grid"><label>{{ t('language') }}<select v-model="form.language"><option value="cs">Čeština</option><option value="en">English</option></select></label><label>{{ t('theme') }}<select v-model="form.theme"><option value="light">{{ t('light') }}</option><option value="dark">{{ t('dark') }}</option><option value="system">{{ t('system') }}</option></select></label><label>{{ t('units') }}<select v-model="form.temperature_unit"><option value="C">Celsius (°C)</option><option value="F">Fahrenheit (°F)</option></select></label></div></section><section class="settings-section"><div><h2>{{ t('heatmap') }}</h2><p>{{ t('thresholdHint') }}</p></div><div><div class="form-grid"><label>{{ t('cold') }} (°C)<input v-model.number="form.heatmap.temperature[0]" type="number" step=".1" min="-50" max="100" required></label><label>{{ t('warm') }} (°C)<input v-model.number="form.heatmap.temperature[1]" type="number" step=".1" min="-50" max="100" required></label><label>{{ t('lowHumidity') }} (%)<input v-model.number="form.heatmap.humidity[0]" type="number" min="0" max="100" required></label><label>{{ t('highHumidity') }} (%)<input v-model.number="form.heatmap.humidity[1]" type="number" min="0" max="100" required></label></div><p class="helper">{{ t('heatmapHint') }}</p><button class="primary" style="margin-top:20px" :disabled="busy">{{ t(busy?'saving':'save') }}</button></div></section></form>
<section class="settings-section"><div><h2>{{ t('collector') }}</h2><p>{{ t('mode') }}: {{ status?.mode }}<br>{{ t('storage') }}: {{ status?.storage }}</p></div><form @submit.prevent="saveSystem"><div class="form-grid"><label>{{ t('sampleInterval') }}<input v-model.number="system.sample_interval_seconds" type="number" min="10" max="86400" required></label><label>{{ t('staleAfter') }}<input v-model.number="system.stale_after_seconds" type="number" min="30" max="604800" required></label></div><button style="margin-top:18px" :disabled="busy">{{ t(busy?'saving':'save') }}</button><Notice v-if="status?.last_error" kind="error">{{ status.last_error }}</Notice></form></section>
<section class="settings-section"><div><h2>{{ t('sensors') }}</h2><p>{{ t('sensorHelp') }}</p><RouterLink class="subtle-link" to="/floorplan">{{ t('floorplan') }} ↗</RouterLink></div><div><div class="page-actions"><button :disabled="scanning||readingAddresses.size>0" @click="discover"><Icon name="sensor" :size="16" />{{ t(readingAddresses.size?'readingSensor':scanning?'scanning':'discover') }}</button><button @click="showSensor()"><Icon name="plus" :size="15" />{{ t('addSensor') }}</button></div><p class="helper">{{ t('scanHelp') }}</p><div v-if="sensorRows.length" class="sensor-list"><article v-for="row in sensorRows" :key="row.key" class="sensor-item"><div><h3>{{ row.name||t('unknown') }} <span class="tag" :class="{warn:rowStatus(row)==='unavailable'}">{{ t(rowStatus(row)) }}</span></h3><p>{{ row.address }}<template v-if="row.rssi!=null"> · {{ row.rssi }} dBm</template><template v-if="row.saved"> · {{ row.saved.sample_interval_seconds }} s</template></p><p v-if="row.temperature!=null&&row.humidity!=null" class="sensor-readings"><strong>{{ formatValue(row.temperature,'temperature') }} {{ unit('temperature') }}</strong><span>{{ formatValue(row.humidity,'humidity') }} %</span></p><p v-if="row.timestamp" class="helper">{{ t('lastSeen') }}: {{ time(row.timestamp) }}</p><p v-if="row.device?.measurement_error&&!readingAddresses.has(row.key)" class="helper">{{ t('sensorReadFailed') }}</p></div><div class="page-actions"><button v-if="row.address&&row.protocol==='lt_thermometer'" :disabled="readingAddresses.has(row.key)" @click="readRow(row)">{{ t('readAgain') }}</button><button :disabled="!row.saved&&row.protocol!=='lt_thermometer'" @click="showSensor(row.saved||row.device)">{{ t(row.saved?'edit':'add') }}</button><button v-if="row.saved" class="text-button danger" @click="removeSensor(row.saved)">{{ t('delete') }}</button></div></article></div><p v-else class="helper">{{ t(scanned?'noDevices':'noSensors') }}</p></div></section>
<section class="settings-section"><div><h2>{{ t('push') }}</h2><p>{{ t('pushNote') }}</p></div><div><p v-if="!pushSupported" class="helper">{{ t('pushUnsupported') }}</p><p v-else-if="!pushAvailable" class="helper">{{ t('pushUnavailable') }}</p><template v-else><p class="helper">{{ t(pushSubscription?'pushSubscribed':'pushUnsubscribed') }}</p><div class="page-actions"><button v-if="!pushSubscription" :disabled="pushBusy" @click="enablePush">{{ t('pushOn') }}</button><button v-else :disabled="pushBusy" @click="disablePush">{{ t('pushOff') }}</button><button :disabled="pushBusy||!pushSubscription" @click="testPush">{{ t('pushTest') }}</button></div></template></div></section>
<section class="settings-section"><div><h2>PWA</h2><p>{{ t('secureOrigin') }}</p></div><div><button v-if="installPrompt" @click="installApp"><Icon name="download" :size="17" />{{ t('install') }}</button><p class="helper">{{ t('installNote') }}</p></div></section>
</template>
<Teleport to="body"><div v-if="sensorOpen" class="modal-backdrop" @pointerdown.self.prevent @keydown.esc="sensorOpen=false"><form v-dialog class="modal" role="dialog" aria-modal="true" :aria-label="t(editing?'editSensor':'addSensor')" @submit.prevent="saveSensor"><header class="modal-header"><h2>{{ t(editing?'editSensor':'addSensor') }}</h2><button type="button" class="icon-button" :aria-label="t('close')" @click="sensorOpen=false"><Icon name="close" /></button></header><Notice v-if="sensorError" kind="error">{{ t('requestFailed') }}<details open><summary>{{ t('details') }}</summary>{{ sensorError }}</details></Notice><div class="form-grid"><label class="full">{{ t('name') }}<input v-model="sensor.name" required maxlength="100"></label><label class="full">{{ t('address') }}<input v-model="sensor.address" required :disabled="!!editing" maxlength="100" placeholder="AA:BB:CC:DD:EE:FF"></label><label>{{ t('sampleInterval') }}<input v-model.number="sensor.sample_interval_seconds" type="number" min="10" max="86400" :disabled="inheritInterval" required><label class="check"><input v-model="inheritInterval" type="checkbox">{{ t('auto') }}</label></label><label class="check"><input v-model="sensor.enabled" type="checkbox">{{ t('enabled') }}</label></div><p class="helper">{{ t('sensorHelp') }}</p><footer class="modal-footer"><button type="button" @click="sensorOpen=false">{{ t('cancel') }}</button><button class="primary" :disabled="busy">{{ t(busy?'saving':'save') }}</button></footer></form></div></Teleport>
</main>
</template>
